body.script:
const MODE     = '';
const SAVE_URL = '';
const CSRF     = '';
let tables       = ;
let waiters      = ;
let allHallTables = ;

'use strict';

let selectedId           = null;
let dragState            = null;
let removedAssignmentIds = [];

// ── Boot ──────────────────────────────────────────────────────────────────────
window.addEventListener('DOMContentLoaded', () => {
    if (MODE === 'hall') {
        document.getElementById('seatedCard').style.display = 'none';
        document.getElementById('occCard').style.display    = 'none';
    } else {
        // Show "Add Table" button only in wedding mode
        document.getElementById('addTableWrap').style.display = '';
        // Show remove button in detail panel (controlled per open)
        document.getElementById('removeBtn').style.display = '';
        // Hint text
        const h = document.getElementById('canvasHint');
        if (allHallTables.length === 0 && tables.length === 0) {
            h.textContent = 'No tables assigned yet — use "+ Add Table" to start';
        } else {
            h.textContent = 'Drag to reposition · Click to configure';
        }
    }
    if (MODE === 'hall') {
        document.getElementById('canvasHint').textContent = 'Drag to reposition · Click to rename';
    }
    render();
});

// Close dropdown when clicking outside
document.addEventListener('click', (e) => {
    const wrap = document.getElementById('addTableWrap');
    if (wrap && !wrap.contains(e.target)) {
        document.getElementById('addTableMenu').classList.remove('open');
    }
});

// ── Render ────────────────────────────────────────────────────────────────────
function render() { renderCanvas(); renderSidebar(); updateStats(); }

function getStatus(t) {
    if (MODE === 'hall') return 'layout';
    if (t.vip) return 'vip';
    const pct = t.capacity ? (t.guests / t.capacity) * 100 : 0;
    return pct === 0 ? 'free' : pct <= 60 ? 'partial' : pct <= 100 ? 'full' : 'over';
}

function renderCanvas() {
    document.querySelectorAll('.tnode').forEach(n => n.remove());
    const canvas = document.getElementById('canvas');
    if (!tables.length) return;

    tables.forEach(t => {
        const shape   = t.shape || 'round';
        const isRect  = (shape === 'rectangular' || shape === 'rect');
        const isOval  = (shape === 'oval');
        const w = isRect ? 116 : 86;
        const h = isRect ? 64  : (isOval ? 60 : 86);
        const status = getStatus(t);

        const node = document.createElement('div');
        node.className = 'tnode' + (selectedId === t.id ? ' sel' : '');
        node.dataset.id = t.id;
        node.style.cssText = `left:${t.x}%;top:${t.y}%;transform:translate(-50%,-50%);`;

        let inner = (t.vip ? '<div class="crown">★</div>' : '') +
            `<div class="tshape s-${shape} st-${status}" style="width:${w}px;height:${h}px;">` +
                `<div class="tlabel">${esc(t.name)}</div>`;
        if (MODE === 'hall') {
            inner += `<div class="tsub">${t.capacity} seats</div>`;
        } else {
            inner += `<div class="tsub">${t.guests}/${t.capacity}</div>` +
                     `<div class="tsub" style="font-size:8px;opacity:.8;">${t.waiter ? t.waiter.split(' ')[0] : ''}</div>`;
        }
        inner += '</div>';
        node.innerHTML = inner;

        node.addEventListener('mousedown', startDrag);
        node.addEventListener('touchstart', startDragTouch, { passive: false });
        node.addEventListener('click', (e) => {
            // Only open detail if this wasn't a drag
            if (!dragState || !dragState.moved) openDetail(t.id);
        });
        canvas.appendChild(node);
    });
}

function renderSidebar() {
    const list = document.getElementById('tableList');
    list.innerHTML = '';
    if (!tables.length) {
        list.innerHTML = '<div style="color:var(--muted);font-size:11px;padding:4px 0;">No tables in plan.</div>';
        return;
    }
    tables.forEach(t => {
        let bc = 'b-layout', bl = t.shape || 'round';
        if (MODE === 'wedding') {
            const pct = t.capacity ? (t.guests / t.capacity) * 100 : 0;
            if (t.vip)             { bc = 'b-vip';     bl = '★ VIP'; }
            else if (pct === 0)    { bc = 'b-free';    bl = 'Free'; }
            else if (pct <= 60)    { bc = 'b-partial'; bl = 'Partial'; }
            else if (pct <= 100)   { bc = 'b-full';    bl = 'Full'; }
            else                   { bc = 'b-over';    bl = 'Over!'; }
        }
        const item = document.createElement('div');
        item.className = 'tli' + (selectedId === t.id ? ' sel' : '') + (t.vip ? ' vip' : '');
        const sub = MODE === 'hall'
            ? t.capacity + ' seats · ' + (t.shape || 'round')
            : t.guests + '/' + t.capacity + ' · ' + (t.waiter || 'No waiter');
        item.innerHTML = `<div class="tli-info">
            <div class="tli-name">${esc(t.name)}</div>
            <div class="tli-sub">${esc(sub)}</div>
          </div><span class="tbadge ${bc}">${esc(bl)}</span>`;
        item.addEventListener('click', () => openDetail(t.id));
        list.appendChild(item);
    });
}

function updateStats() {
    const cap    = tables.reduce((s, t) => s + (t.capacity || 0), 0);
    const seated = tables.reduce((s, t) => s + (t.guests   || 0), 0);
    const occ    = cap ? Math.round(seated / cap * 100) : 0;
    document.getElementById('statTables').textContent = tables.length;
    document.getElementById('statCap').textContent    = cap;
    document.getElementById('statSeated').textContent = seated;
    document.getElementById('statOcc').textContent    = MODE === 'hall' ? '—' : occ + '%';
}

// ── Mouse Drag ─────────────────────────────────────────────────────────────────
function startDrag(e) {
    if (e.button !== 0) return;
    e.preventDefault();
    const id  = e.currentTarget.dataset.id;
    const t   = tables.find(x => x.id === id);
    if (!t) return;
    const rect = document.getElementById('canvas').getBoundingClientRect();
    dragState = { id, startX: e.clientX, startY: e.clientY,
                  origX: t.x, origY: t.y, rect, moved: false };
    e.currentTarget.classList.add('dragging');
    window.addEventListener('mousemove', onDrag);
    window.addEventListener('mouseup', endDrag);
}

function onDrag(e) {
    if (!dragState) return;
    const dx = e.clientX - dragState.startX;
    const dy = e.clientY - dragState.startY;
    if (!dragState.moved && Math.abs(dx) + Math.abs(dy) > 4) dragState.moved = true;
    if (!dragState.moved) return;
    const t = tables.find(x => x.id === dragState.id);
    if (!t) return;
    t.x = Math.max(4, Math.min(96, dragState.origX + (dx / dragState.rect.width)  * 100));
    t.y = Math.max(14, Math.min(93, dragState.origY + (dy / dragState.rect.height) * 100));
    const node = document.querySelector(`.tnode[data-id="${CSS.escape(dragState.id)}"]`);
    if (node) { node.style.left = t.x + '%'; node.style.top = t.y + '%'; }
}

function endDrag(e) {
    if (dragState) {
        const node = document.querySelector(`.tnode[data-id="${CSS.escape(dragState.id)}"]`);
        if (node) node.classList.remove('dragging');
    }
    window.removeEventListener('mousemove', onDrag);
    window.removeEventListener('mouseup', endDrag);
    // Small delay so click handler can read dragState.moved before we clear it
    setTimeout(() => { dragState = null; }, 80);
}

// ── Touch Drag ─────────────────────────────────────────────────────────────────
function startDragTouch(e) {
    if (e.touches.length !== 1) return;
    e.preventDefault();
    const touch = e.touches[0];
    const id    = e.currentTarget.dataset.id;
    const t     = tables.find(x => x.id === id);
    if (!t) return;
    const rect = document.getElementById('canvas').getBoundingClientRect();
    dragState = { id, startX: touch.clientX, startY: touch.clientY,
                  origX: t.x, origY: t.y, rect, moved: false };
    e.currentTarget.classList.add('dragging');
    window.addEventListener('touchmove', onDragTouch, { passive: false });
    window.addEventListener('touchend',  endDragTouch);
}

function onDragTouch(e) {
    if (!dragState || e.touches.length !== 1) return;
    e.preventDefault();
    const touch = e.touches[0];
    const dx = touch.clientX - dragState.startX;
    const dy = touch.clientY - dragState.startY;
    if (!dragState.moved && Math.abs(dx) + Math.abs(dy) > 6) dragState.moved = true;
    if (!dragState.moved) return;
    const t = tables.find(x => x.id === dragState.id);
    if (!t) return;
    t.x = Math.max(4, Math.min(96, dragState.origX + (dx / dragState.rect.width)  * 100));
    t.y = Math.max(14, Math.min(93, dragState.origY + (dy / dragState.rect.height) * 100));
    const node = document.querySelector(`.tnode[data-id="${CSS.escape(dragState.id)}"]`);
    if (node) { node.style.left = t.x + '%'; node.style.top = t.y + '%'; }
}

function endDragTouch(e) {
    if (dragState) {
        const node = document.querySelector(`.tnode[data-id="${CSS.escape(dragState.id)}"]`);
        if (node) node.classList.remove('dragging');
        if (!dragState.moved) openDetail(dragState.id);
    }
    window.removeEventListener('touchmove', onDragTouch);
    window.removeEventListener('touchend',  endDragTouch);
    setTimeout(() => { dragState = null; }, 80);
}

// ── Add Table (wedding mode only) ─────────────────────────────────────────────
function toggleAddTableMenu(e) {
    e.stopPropagation();
    const menu = document.getElementById('addTableMenu');
    if (menu.classList.contains('open')) {
        menu.classList.remove('open');
        return;
    }
    buildAddTableMenu();
    menu.classList.add('open');
}

function buildAddTableMenu() {
    const listEl = document.getElementById('addTableList');
    const usedPhysIds = new Set(tables.map(t => t.phys_id));
    const available = allHallTables.filter(t => !usedPhysIds.has(t.phys_id));
    if (!available.length) {
        listEl.innerHTML = '<div class="atm-empty">All hall tables are already in the plan.</div>';
        return;
    }
    listEl.innerHTML = available.map(t => `
      <div class="atm-item" onclick="addTableToCanvas(${t.phys_id})">
        <div>
          <div class="atm-name">${esc(t.name)}</div>
          <div class="atm-sub">${t.capacity} seats · ${t.shape}</div>
        </div>
        <span style="font-size:18px;color:var(--success);">＋</span>
      </div>`).join('');
}

function addTableToCanvas(physId) {
    const phys = allHallTables.find(t => t.phys_id === physId);
    if (!phys) return;
    if (tables.find(t => t.phys_id === physId)) {
        toast('Table already in plan', 'info');
        return;
    }
    // Place new table in the center, slightly offset if others are nearby
    const cx = 40 + (tables.length % 4) * 13;
    const cy = 45 + Math.floor(tables.length / 4) * 20;
    tables.push({
        id:            'new_' + physId,
        phys_id:       physId,
        assignment_id: 0,
        name:          phys.name,
        shape:         phys.shape || 'round',
        capacity:      phys.capacity || 8,
        guests:        0,
        waiter:        '',
        waiter_id:     0,
        vip:           false,
        notes:         '',
        x:             Math.min(cx, 88),
        y:             Math.min(cy, 85),
    });
    document.getElementById('addTableMenu').classList.remove('open');
    render();
    toast(phys.name + ' added to plan', 'success');
    // Update hint
    document.getElementById('canvasHint').textContent = 'Drag to reposition · Click to configure';
}

function removeSelectedTable() {
    if (!selectedId) return;
    const t = tables.find(x => x.id === selectedId);
    if (!t) return;
    if (!confirm('Remove "' + t.name + '" from this event plan?')) return;
    if (t.assignment_id) {
        removedAssignmentIds.push(t.assignment_id);
    }
    tables = tables.filter(x => x.id !== selectedId);
    closeDetail();
    render();
    toast(t.name + ' removed from plan', 'info');
}

// ── Detail Panel ──────────────────────────────────────────────────────────────
function openDetail(id) {
    selectedId = id;
    const t = tables.find(x => x.id === id);
    if (!t) return;

    document.getElementById('detTitle').textContent = t.name;
    const body = document.getElementById('detBody');

    if (MODE === 'hall') {
        body.innerHTML = `
          <div class="frow">
            <div class="flbl">Table Name</div>
            <input class="finput" id="dName" value="${esc(t.name)}" placeholder="Table name..."/>
          </div>
          <div class="frow">
            <div class="flbl">Shape</div>
            <select class="fselect" id="dShape">
              ${['round','rectangular','square','oval'].map(s =>
                `<option value="${s}"${t.shape===s?' selected':''}>${s.charAt(0).toUpperCase()+s.slice(1)}</option>`
              ).join('')}
            </select>
          </div>
          <div class="frow">
            <div class="flbl">Capacity (seats)</div>
            <input class="finput" type="number" id="dCap" value="${t.capacity}" min="1" max="50"/>
          </div>`;
        // Hide remove button in hall mode
        document.getElementById('removeBtn').style.display = 'none';
    } else {
        const pct = t.capacity ? Math.min((t.guests / t.capacity) * 100, 150) : 0;
        const barClr = occBarColor(pct);
        const waiterOpts = '<option value="0">— No Waiter —</option>' +
            waiters.map(w =>
                `<option value="${w.id}"${t.waiter_id === w.id ? ' selected' : ''}>${esc(w.name)}</option>`
            ).join('');
        body.innerHTML = `
          <div class="frow">
            <div class="flbl">Table · Shape · Capacity</div>
            <div class="fval">${esc(t.name)} · ${t.shape} · ${t.capacity} seats</div>
          </div>
          <div class="frow">
            <div class="flbl">Guests to Seat</div>
            <input class="finput" type="number" id="dGuests" value="${t.guests}"
                   min="0" max="${Math.ceil(t.capacity * 1.5)}"
                   oninput="liveOcc(this.value)"/>
            <div class="occ-wrap" style="margin-top:6px;">
              <div class="occ-bar" id="occBar"
                   style="width:${Math.min(pct,100)}%;background:${barClr};"></div>
            </div>
            <div id="occPct" style="font-size:10px;color:var(--muted);margin-top:3px;">
              ${Math.round(pct)}% occupancy
            </div>
          </div>
          <div class="frow">
            <div class="flbl">Assigned Waiter</div>
            <select class="fselect" id="dWaiter">${waiterOpts}</select>
          </div>
          <div class="frow">
            <div class="flbl">VIP Table</div>
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:2px 0;">
              <input type="checkbox" id="dVip" ${t.vip ? 'checked' : ''}
                     onchange="toggleVip()" style="width:16px;height:16px;cursor:pointer;"/>
              <span style="font-size:13px;">Mark as VIP ★</span>
            </label>
          </div>
          <div class="frow">
            <div class="flbl">Special Notes</div>
            <input class="finput" id="dNotes" value="${esc(t.notes || '')}"
                   placeholder="Any special requirements..."/>
          </div>`;
        document.getElementById('removeBtn').style.display = 'flex';
    }

    document.getElementById('detailPanel').classList.add('open');
    renderSidebar();
    renderCanvas();
}

function closeDetail() {
    selectedId = null;
    document.getElementById('detailPanel').classList.remove('open');
    render();
}

function occBarColor(pct) {
    if (pct === 0)       return 'var(--success)';
    if (pct <= 60)       return 'var(--gold)';
    if (pct <= 100)      return 'var(--accent)';
    return 'var(--danger)';
}

function liveOcc(val) {
    const t = tables.find(x => x.id === selectedId);
    if (!t) return;
    const pct = t.capacity ? Math.min((parseInt(val) || 0) / t.capacity * 100, 150) : 0;
    const bar = document.getElementById('occBar');
    if (bar) {
        bar.style.width      = Math.min(pct, 100) + '%';
        bar.style.background = occBarColor(pct);
        document.getElementById('occPct').textContent = Math.round(pct) + '% occupancy';
    }
}

function toggleVip() {
    const t  = tables.find(x => x.id === selectedId);
    const cb = document.getElementById('dVip');
    if (t && cb) { t.vip = cb.checked; renderCanvas(); renderSidebar(); }
}

function applyDetail() {
    const t = tables.find(x => x.id === selectedId);
    if (!t) return;
    if (MODE === 'hall') {
        const nameVal = document.getElementById('dName')?.value.trim();
        if (nameVal) t.name = nameVal;
        const shapeVal = document.getElementById('dShape')?.value;
        if (shapeVal) t.shape = shapeVal;
        const capVal = parseInt(document.getElementById('dCap')?.value);
        if (capVal > 0) t.capacity = capVal;
        document.getElementById('detTitle').textContent = t.name;
    } else {
        t.guests = parseInt(document.getElementById('dGuests')?.value) || 0;
        const sel    = document.getElementById('dWaiter');
        t.waiter_id  = parseInt(sel?.value) || 0;
        t.waiter     = t.waiter_id > 0 ? (sel?.selectedOptions[0]?.text || '') : '';
        t.vip        = document.getElementById('dVip')?.checked || false;
        t.notes      = document.getElementById('dNotes')?.value || '';
    }
    render();
    toast('Changes applied', 'success');
}

function applyAndClose() { applyDetail(); closeDetail(); }

// ── Save to Odoo ──────────────────────────────────────────────────────────────
async function savePlan() {
    const btn = document.getElementById('saveBtn');
    btn.disabled = true;
    btn.textContent = '⏳ Saving…';

    const payload = tables.map(t => ({
        phys_id:       t.phys_id || 0,
        assignment_id: t.assignment_id || 0,
        name:          t.name,
        shape:         t.shape,
        capacity:      t.capacity,
        guests:        t.guests    || 0,
        waiter_id:     t.waiter_id || 0,
        vip:           t.vip       || false,
        notes:         t.notes     || '',
        x:             Math.round(t.x),
        y:             Math.round(t.y),
    }));

    try {
        const res = await fetch(SAVE_URL, {
            method:  'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken':  CSRF,
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method:  'call',
                id:      1,
                params:  {
                    tables:      payload,
                    removed_ids: removedAssignmentIds,
                },
            }),
        });
        const data = await res.json();
        if (data.result && data.result.success) {
            removedAssignmentIds = [];
            toast('Floor plan saved ✓', 'success');
            // After a successful save, reload to get fresh IDs for newly created assignments
            if (MODE === 'wedding' && payload.some(t => !t.assignment_id)) {
                setTimeout(() => location.reload(), 900);
            }
        } else {
            const errMsg = (data.result && data.result.error)
                ? data.result.error
                : (data.error ? JSON.stringify(data.error) : 'Unknown error');
            toast('Save failed: ' + errMsg, 'error');
        }
    } catch (err) {
        toast('Network error: ' + err.message, 'error');
    } finally {
        btn.disabled = false;
        btn.textContent = '💾 Save';
    }
}

// ── Reset Layout ──────────────────────────────────────────────────────────────
function resetLayout() {
    if (!tables.length) return;
    if (!confirm('Reset all table positions to a grid layout?')) return;
    tables.forEach((t, i) => {
        t.x = 12 + ((i % 5) * 17);
        t.y = 38 + (Math.floor(i / 5) * 24);
    });
    render();
    toast('Layout reset to grid', 'info');
}

// ── Utils ─────────────────────────────────────────────────────────────────────
function esc(s) {
    return String(s ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

let toastTimer;
function toast(msg, type) {
    type = type || 'info';
    const el   = document.getElementById('toast');
    const icon = { success: '✓', error: '✗', info: 'ℹ' }[type] || 'ℹ';
    document.getElementById('toastIcon').textContent = icon;
    document.getElementById('toastMsg').textContent  = msg;
    el.className = 'toast ' + type + ' show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('show'), 3200);
}
